<script setup>
import { computed, onMounted, ref } from 'vue'
import { getCities, getProvinces } from '../api/location'
import { getAirQualityCities, getAirQualityLevels, getAirQualityOverview, getAirQualityProvinces } from '../api/airQuality'
import BigScreenLayout from '../components/layout/BigScreenLayout.vue'
import ChartState from '../components/dashboard/ChartState.vue'
import DashboardPanel from '../components/dashboard/DashboardPanel.vue'
import AirQualityMap from '../components/airQuality/AirQualityMap.vue'
import AirQualityDistributionChart from '../components/airQuality/AirQualityDistributionChart.vue'
import { dataRegion, setDataRegion } from '../stores/regionStore'
import { aqiStatusClass, aqiStatusColor, formatDateTime } from '../utils/formatters'
import { sameAirQualityCity } from '../utils/airQualityRegion'

const provinces=ref([]), cities=ref([]), province=ref(dataRegion.province || ''), city=ref(dataRegion.city || ''), overview=ref(null), provinceRows=ref([]), cityRows=ref([]), levels=ref([]), selected=ref(null), loading=ref(true), error=ref(''), cityLoading=ref(false), requestVersion=ref(0)
const goodRate = computed(() => { const total=Number(overview.value?.cityCount||0); return total ? `${((Number(overview.value?.goodCityCount||0)/total)*100).toFixed(1)}%` : '暂无数据' })
const pollutedTop = computed(() => cityRows.value.slice().sort((a,b)=>(b.aqi??-1)-(a.aqi??-1)).slice(0,10))
const goodTop = computed(() => cityRows.value.slice().sort((a,b)=>(a.aqi??Infinity)-(b.aqi??Infinity)).slice(0,10))
const detail = computed(() => selected.value || (city.value ? { province: province.value, city: city.value, aqi: null, status: null, createdAt: null } : null))
const detailCity = computed(() => cities.value.find((name) => sameAirQualityCity(name, detail.value?.city)) || detail.value?.city || '')
const titleScope = computed(() => province.value ? `${province.value}空气质量快照` : '全国空气质量快照')
function selectStatus(row){ return row?.status || '暂无等级' }
function updateRegion(){ setDataRegion({ province:province.value, city:city.value, district:'', scope:city.value?'city':province.value?'province':'country' }) }
async function loadAll(token=++requestVersion.value){ loading.value=true; error.value=''; overview.value=null; cityRows.value=[]; levels.value=[]; selected.value=null; try { const [p,o,s,c,l] = await Promise.all([getProvinces(),getAirQualityOverview(province.value?{province:province.value}:{}),getAirQualityProvinces(),getAirQualityCities(province.value?{province:province.value}:{}),getAirQualityLevels(province.value?{province:province.value}:{})]); if(token!==requestVersion.value)return; provinces.value=Array.isArray(p.data)?p.data:[]; overview.value=o.data||null; provinceRows.value=Array.isArray(s.data)?s.data:[]; cityRows.value=Array.isArray(c.data)?c.data:[]; levels.value=Array.isArray(l.data)?l.data:[]; selected.value=cityRows.value.find(x=>sameAirQualityCity(x.city, city.value))||null } catch (reason) { if(token===requestVersion.value) error.value=reason?.message?`空气质量数据读取失败：${reason.message}`:'空气质量数据读取失败' } finally { if(token===requestVersion.value) loading.value=false } }
async function provinceChange(value){ const token=++requestVersion.value; province.value=value; city.value=''; selected.value=null; updateRegion(); cityLoading.value=true; try { if(value){ const r=await getCities({province:value}); if(token!==requestVersion.value)return; cities.value=Array.isArray(r.data)?r.data:[] } else cities.value=[]; await loadAll(token) } catch(reason) { if(token===requestVersion.value) error.value=reason?.message?`区域数据读取失败：${reason.message}`:'区域数据读取失败' } finally { if(token===requestVersion.value) cityLoading.value=false } }
async function cityChange(value){ city.value=value; updateRegion(); selected.value=cityRows.value.find(x=>sameAirQualityCity(x.city,value))||null }
function chooseCity(row){ selected.value=row; city.value=cities.value.find((name) => sameAirQualityCity(name, row.city)) || row.city; updateRegion() }
function healthAdvice(status){ if(status==='优'||status==='良') return '空气质量适宜大多数人群活动。'; if(status==='轻度污染') return '敏感人群适量减少长时间户外活动。'; if(status) return '建议敏感人群减少户外活动并关注防护。'; return '暂无健康建议。' }
onMounted(async()=>{ if(province.value){ await provinceChange(province.value) } else await loadAll() })
</script>
<template>
<BigScreenLayout page-number="5" title="空气质量分析" description="基于真实空气质量快照分析城市样本 AQI。" header-status="空气质量快照" toolbar-status="快照数据 · 不代表实时更新">
<template #filters><div class="aq-filter"><strong>区域筛选</strong><label>省份<select :value="province" :disabled="loading" @change="provinceChange($event.target.value)"><option value="">全国</option><option v-for="x in provinces" :key="x" :value="x">{{x}}</option></select></label><label>城市<select :value="city" :disabled="loading||cityLoading||!province" @change="cityChange($event.target.value)"><option value="">全部城市</option><option v-for="x in cities" :key="x" :value="x">{{x}}{{cityRows.some(row=>sameAirQualityCity(row.city,x))?'':'（暂无AQI快照）'}}</option></select></label><button type="button" class="aq-national-button" :disabled="loading||(!province&&!city)" @click="provinceChange('')">返回全国</button><span>快照时间：{{formatDateTime(overview?.createdAt)||'暂无快照'}}</span></div></template>
<p v-if="error" class="aq-alert">{{error}}</p><div class="aq-page"><DashboardPanel title="空气质量核心指标" :subtitle="titleScope"><ChartState :loading="loading" :error="''" :empty="!overview" empty-message="暂无有效空气质量快照"><div class="aq-metrics"><article><b>▥</b><span>监测城市数<strong>{{overview?.cityCount??'暂无数据'}}<small> 个</small></strong></span></article><article><b>◉</b><span>城市样本平均 AQI<strong>{{overview?.averageAqi??'暂无数据'}}</strong></span></article><article><b>◒</b><span>优良空气城市数<strong>{{overview?.goodCityCount??'暂无数据'}}<small> 个 · {{goodRate}}</small></strong></span></article><article><b>!</b><span>轻度污染及以上<strong>{{overview?.pollutedCityCount??'暂无数据'}}<small> 个</small></strong></span></article></div></ChartState></DashboardPanel><div class="aq-grid"><div class="aq-left"><DashboardPanel title="污染城市排行 TOP10" subtitle="AQI 从高到低 · 最新城市快照"><ChartState :loading="loading" :error="''" :empty="!pollutedTop.length" empty-message="暂无污染城市数据"><div class="aq-table"><div class="aq-head"><span>排名</span><span>城市</span><span>省份</span><span>AQI</span><span>等级</span></div><button v-for="(x,i) in pollutedTop" :key="`${x.province}-${x.city}`" class="aq-row" type="button" @click="chooseCity(x)"><span>{{i+1}}</span><span>{{x.city}}</span><span>{{x.province}}</span><strong :style="{color:aqiStatusColor(x.status)}">{{x.aqi??'暂无数据'}}</strong><span :class="aqiStatusClass(x.status)">{{selectStatus(x)}}</span></button></div></ChartState></DashboardPanel><DashboardPanel title="空气质量等级分布" subtitle="按 AQI 数值分类"><AirQualityDistributionChart :data="levels" :loading="loading" :error="''"/></DashboardPanel></div><DashboardPanel class="aq-map-panel" title="全国 AQI 分布" subtitle="颜色按城市样本平均 AQI · 点击省份筛选"><AirQualityMap :data="provinceRows" :loading="loading" :error="''" :selected-province="province" @province-select="provinceChange"/></DashboardPanel><div class="aq-right"><DashboardPanel title="优质空气城市 TOP10" subtitle="AQI 从低到高 · 最新城市快照"><ChartState :loading="loading" :error="''" :empty="!goodTop.length" empty-message="暂无优质城市数据"><div class="aq-table"><div class="aq-head"><span>排名</span><span>城市</span><span>省份</span><span>AQI</span><span>等级</span></div><button v-for="(x,i) in goodTop" :key="`${x.province}-${x.city}`" class="aq-row" type="button" @click="chooseCity(x)"><span>{{i+1}}</span><span>{{x.city}}</span><span>{{x.province}}</span><strong :style="{color:aqiStatusColor(x.status)}">{{x.aqi??'暂无数据'}}</strong><span :class="aqiStatusClass(x.status)">{{selectStatus(x)}}</span></button></div></ChartState></DashboardPanel><DashboardPanel title="城市空气质量查询" subtitle="真实快照 · 无历史趋势"><div class="aq-query"><label>城市<select :value="city" :disabled="cityLoading||!province" @change="cityChange($event.target.value)"><option value="">请选择城市</option><option v-for="x in cities" :key="x" :value="x">{{x}}{{cityRows.some(row=>sameAirQualityCity(row.city,x))?'':'（暂无AQI快照）'}}</option></select></label><ChartState :loading="cityLoading" :error="''" :empty="!detail" empty-message="请选择城市"><div class="aq-detail"><div><small>{{detail?.province}} · {{detailCity}}</small><strong>{{detail?.aqi??'暂无数据'}}</strong><span :class="aqiStatusClass(detail?.status)">{{selectStatus(detail)}}</span></div><p>快照时间：{{formatDateTime(detail?.createdAt)||'暂无数据'}}</p><p>首要污染物：暂无该字段</p><p>健康提示：{{healthAdvice(detail?.status)}}</p></div></ChartState></div></DashboardPanel></div></div></div>
</BigScreenLayout></template>
<style scoped>
.aq-filter{display:flex;align-items:center;gap:18px;padding:7px 13px;color:var(--text-muted);font-size:11px;background:linear-gradient(90deg,rgb(6 42 81/.92),rgb(4 28 61/.84));border:1px solid rgb(35 143 211/.58);border-radius:6px}.aq-filter strong{color:var(--accent-cyan);font-size:13px}.aq-filter label{display:inline-flex;align-items:center;gap:7px}.aq-filter select{height:32px;min-width:145px;padding:5px 22px 5px 9px;color:var(--text-primary);font:inherit;background:#0b315f;border:1px solid rgb(45 151 216/.68);border-radius:4px}.aq-national-button{height:32px;padding:0 12px;color:#eafaff;background:#0b5fa8;border:1px solid #34d2ff;border-radius:4px;cursor:pointer}.aq-national-button:disabled{cursor:not-allowed;opacity:.55}.aq-filter span{margin-left:auto}.aq-alert{margin:0;padding:8px 12px;color:var(--danger);background:rgb(100 24 48/.32);border:1px solid rgb(255 125 134/.4);border-radius:6px}.aq-page{display:flex;min-height:0;flex:1;flex-direction:column;gap:12px}.aq-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.aq-metrics article{display:flex;min-height:92px;align-items:center;gap:14px;padding:14px;background:linear-gradient(145deg,rgb(7 49 94/.8),rgb(3 26 58/.78));border:1px solid rgb(36 145 211/.52);border-radius:7px}.aq-metrics b{display:grid;width:46px;height:46px;place-items:center;color:#63d9ff;font-size:25px;background:rgb(12 94 157/.38);border:1px solid rgb(73 205 255/.45);border-radius:50%}.aq-metrics span{color:var(--text-secondary);font-size:12px}.aq-metrics strong{display:block;margin-top:5px;color:var(--text-primary);font-size:24px}.aq-metrics small{font-size:11px}.aq-grid{display:grid;min-height:0;grid-template-columns:minmax(270px,1fr) minmax(480px,1.7fr) minmax(270px,1fr);gap:12px}.aq-left,.aq-right{display:grid;min-width:0;gap:12px;grid-template-rows:minmax(330px,1fr) minmax(260px,auto)}.aq-map-panel{min-height:610px}.aq-head,.aq-row{display:grid;grid-template-columns:34px 1.15fr 1fr 44px .9fr;gap:5px;align-items:center}.aq-head{padding:8px 9px;color:var(--text-secondary);font-size:10px;background:rgb(10 57 103/.7)}.aq-row{width:100%;padding:7px 9px;color:var(--text-secondary);font:inherit;text-align:left;background:transparent;border:0;border-bottom:1px solid rgb(39 112 161/.24);cursor:pointer}.aq-row:hover{background:rgb(31 119 174/.24)}.aq-row strong{font-size:13px}.aqi-good{color:var(--accent-green)}.aqi-moderate{color:#f4d35e}.aqi-light{color:#ff9f43}.aqi-medium{color:#ff6b6b}.aqi-heavy{color:#c56cf0}.aqi-severe{color:#ff4f76}.aq-query label{display:flex;align-items:center;gap:8px;color:var(--text-muted);font-size:12px}.aq-query select{flex:1;height:32px;color:var(--text-primary);background:#0b315f;border:1px solid rgb(45 151 216/.68);border-radius:4px}.aq-detail{margin-top:14px;padding:13px;background:rgb(4 36 74/.72);border:1px solid rgb(37 143 210/.45);border-radius:6px}.aq-detail>div{display:flex;align-items:center;gap:12px}.aq-detail small{color:var(--text-secondary)}.aq-detail strong{color:var(--text-primary);font-size:28px}.aq-detail span{padding:4px 11px;border-radius:12px;background:rgb(52 218 159/.18)}.aq-detail p{margin:10px 0 0;color:var(--text-secondary);font-size:11px;line-height:1.5}@media(max-width:1200px){.aq-grid{grid-template-columns:1fr 1.4fr}.aq-right{grid-column:1 / -1;grid-template-columns:1fr 1fr}.aq-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.aq-filter{align-items:flex-start;flex-direction:column}.aq-filter span{margin-left:0}.aq-grid{grid-template-columns:1fr}.aq-left,.aq-right{grid-template-rows:auto}.aq-right{grid-column:auto}.aq-metrics{grid-template-columns:1fr}}
</style>
